import assert from "node:assert/strict"
import fs from "node:fs"
import os from "node:os"
import {join, dirname, relative} from "node:path"
import type {TestContext} from "node:test"
import {test} from "node:test"

import {TraceMap, originalPositionFor} from "@jridgewell/trace-mapping"

import {strip_types, strip_modules} from "#compiler/strip.js"

type Files = {[file: string]: string}

/** Creates a temporary extension with `files` and returns its directory. */
function fixture(t: TestContext, files: Files): string {
  const dir = fs.mkdtempSync(join(os.tmpdir(), "bokehjs-test-strip-"))
  t.after(() => fs.rmSync(dir, {recursive: true, force: true}))
  for (const [file, source] of Object.entries(files)) {
    const path = join(dir, file)
    fs.mkdirSync(dirname(path), {recursive: true})
    fs.writeFileSync(path, source, {encoding: "utf-8"})
  }
  return dir
}

const read = (dir: string, file: string) => fs.readFileSync(join(dir, file), "utf-8")
const exists = (dir: string, file: string) => fs.existsSync(join(dir, file))

void test("strip_types() strips types and transforms TypeScript-only syntax", () => {
  const result = strip_types("a.ts", "import type {T} from \"./t\"\nexport enum E { A }\nexport const a: T = E.A as number\n")
  assert.ok(!("errors" in result))
  assert.doesNotMatch(result.code, /import|: T|as number/)
  assert.match(result.code, /E\[E\["A"\] = 0\] = "A"/)
})

void test("strip_types() reports syntax errors and unsupported syntax", () => {
  const syntax = strip_types("a.ts", "const a: = 1")
  assert.ok("errors" in syntax)
  assert.match(syntax.errors[0], /Unexpected token[^]*a\.ts:1:10/)

  const decorators = strip_types("a.ts", "declare const d: any\n@d class A {}")
  assert.ok("errors" in decorators)
  assert.match(decorators.errors[0], /unsupported syntax/)
})

void test("strip_modules() writes modules reachable from the entry with source maps", (t) => {
  const dir = fixture(t, {
    "index.ts": "export {a} from \"./a.js\"\nimport \"./sub\"\nexport const lazy = () => import(\"./lazy\")\n",
    "a.ts": "import {b} from \"./b\"\nexport const a: number = b\n",
    "b.js": "export const b = 1\n",
    "sub/index.ts": "import css from \"../styles/x.css\"\nexport const sub: string = css\n",
    "lazy.ts": "export const lazy = 1\n",
    "unused.ts": "export const unused = 1\n",
    "lib/styles/x.css.js": "export default \"\"\n", // generated by `wrap_css_modules()`
  })
  const lib = join(dir, "lib")
  const {files, errors} = strip_modules(join(dir, "index.ts"), dir, lib)
  assert.deepEqual(errors, [])
  assert.deepEqual(files.map((file) => relative(dir, file).replaceAll("\\", "/")).sort(), ["a.ts", "b.js", "index.ts", "lazy.ts", "sub/index.ts"])
  assert.ok(!exists(lib, "unused.js"))

  const a = read(lib, "a.js")
  assert.match(a, /export const a = b;/)
  assert.match(a, /\/\/# sourceMappingURL=a\.js\.map\n$/)

  const map = JSON.parse(read(lib, "a.js.map"))
  assert.deepEqual(map.sources, ["../a.ts"])
  const lines = a.slice(0, a.indexOf("a = b")).split("\n")
  const position = originalPositionFor(new TraceMap(map), {line: lines.length, column: lines[lines.length - 1].length})
  assert.deepEqual([position.source, position.line], ["../a.ts", 2])
})

void test("strip_modules() reports unresolved relative imports and syntax errors", (t) => {
  const dir = fixture(t, {
    "index.ts": "import \"./a\"\nimport \"./missing\"\nimport \"@bokehjs/base\"\n",
    "a.ts": "const a: = 1\n",
  })
  const {errors} = strip_modules(join(dir, "index.ts"), dir, join(dir, "lib"))
  assert.equal(errors.length, 2)
  assert.match(errors[0], /index\.ts:2:8 - error: can't resolve '\.\/missing'/)
  assert.match(errors[1], /Unexpected token/)
})
